const db=$getWorkflowStaticData('global');
const recent=(Array.isArray(db.usedTopics)?db.usedTopics:[]).slice(-24);
const themes=["aile grubunda yanlış anlaşılma","amcanın teknolojiyle imtihanı","sevgilinin kıskançlığı","yanlış numaraya mesaj","akşam yemeği karmaşası","annenin yanlış anlaması","babanın sürprizi","amcanın borç isteği","kardeş şakası","ilk buluşma karışıklığı","kankanın ses kaydı","bayram aile grubu","otomatik düzeltme faciası","gizemli kargo","ninenin teknoloji keşfi","sevgiliyle komik diyalog","evcil hayvan mesajı"];
const theme=themes[Math.floor(Math.random()*themes.length)];
const prompt=`Tamamen ÖZGÜN, günlük Türkiye Türkçesinde doğal ve seslendirilen komik bir mesajlaşma hikâyesi yaz; başka kanallardan kopyalama veya çeviri olmasın.
Konu: ${theme}
AMAÇ: Shorts akışında ilk anda kaydırmayı durdurmak; ana sayfada görünen başlık ve video kapağıyla merak uyandırmak.
- Tek bir SOMUT, gündelik, sürprizli yanlış anlaşılma seç. Genel 'komik sohbet' klişesi yazma.
- İLK MESAJ anında olaya girsin: şok edici ama inandırıcı soru, açıklama veya suçlama. En fazla 55 karakter; selamlaşma, giriş, 'naber' ve uzun hazırlık yok.
- İKİNCİ MESAJ merakı ve yanlış anlaşılmayı artırmalı; en fazla 65 karakter.
- Sohbet gittikçe büyüsün; son mesajda mantıklı ama beklenmedik, komik bir ters köşe olsun. Sonucu başlıkta/kapağında SÖYLEME.
- 11-13 mesaj, toplam yaklaşık 75-100 TÜRKÇE kelime (seslendirmeyle 30-45 saniye hedefi, gerçek süre TTS'ye bağlı). Kısa, doğal, net; her mesaj en fazla 180 karakter.
- 'me' ve şu rollerden birini kullan: girlfriend,boyfriend,mother,father,grandpa,grandma,uncle,aunt,friend,sister,brother; en fazla 3 kişi, mümkünse 2. Ses/rol tutarlı kalsın. Gerçek kişiler değil, kurgu.
- coverText: olayın en dikkat çekici, DOĞRU, merak uyandıran Türkçe başlığı; 12-36 karakter, 2-6 kelime, kısa ve büyük harfle yazmaya uygun. Final sürprizini açıklama. Emoji/hashtag kullanma. Biçim örnekleri: 'AMCAM NE YAPTI?', 'SEVGİLİM YAKALADI', 'BABAM YANLIŞ KİŞİYE YAZDI'.
- youtubeTitle: özgün, dikkat çekici, 35-65 karakter, gerçek içerikle uyumlu. İlk kelimelerde karakteri veya şaşırtıcı olayı söyle. Sonunda '#shorts' olsun. Yanıltıcı iddia, abartılı büyük harf, uzun başlık yok.
- youtubeDescription: kurgusal ve yapay zekâyla seslendirilmiş sohbet olduğunu 1-2 cümleyle belirt; 3-5 ilgili basit hashtag.
- Küfür, aşağılama, telifli karakter, gerçek kişiyi taklit veya ünlü şarkılar yok.
- Şu yeni konuları/ters köşeleri tekrar etme: ${JSON.stringify(recent)}.
YALNIZCA şu anahtarları içeren GEÇERLİ JSON döndür:
{"chatTitle":"kısa kişi/sohbet adı maks 24 karakter","coverText":"merak başlığı maks 36 karakter","topic":"özgün olay maks 100 karakter","youtubeTitle":"ilgi çekici Türkçe başlık #shorts","youtubeDescription":"yapay zekâyla seslendirilmiş kurgu sohbet açıklaması","hashtags":["shorts","komikmesajlar","komedi"],"dialogue":[{"speaker":"me","text":"şok edici kısa ilk mesaj"},{"speaker":"uncle","text":"merakı artıran cevap"}]}
Markdown, anlatıcı, açıklama veya fazladan alan yok.`;
return [{json:{body:{contents:[{role:'user',parts:[{text:prompt}]}],generationConfig:{responseMimeType:'application/json',temperature:1.0,maxOutputTokens:3200}}}}];

const text=$input.first().json.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'';
if(!text)throw new Error('Gemini cevap vermedi, yeni video istenmedi.');
let o;try{o=JSON.parse(text.replace(/^\x60\x60\x60json\\s*/i,'').replace(/\x60\x60\x60$/,'').trim());}catch(e){throw new Error('Gemini JSON hatasi: '+text.slice(0,150));}
const allowed=new Set(['me','girlfriend','boyfriend','mother','father','grandpa','grandma','uncle','aunt','friend','sister','brother']);
const d=o.dialogue;
if(!Array.isArray(d)||d.length<11||d.length>14||d.some(x=>!allowed.has(x.speaker)||typeof x.text!=='string'||x.text.length<2||x.text.length>180)||new Set(d.map(x=>x.speaker)).size>3||!d.some(x=>x.speaker==='me'))throw new Error('Diyalog kalite/ses esleme kurali gecemedi; render iptal.');
const titleRaw=String(o.youtubeTitle||'Funny Text Messages').replace(/#shorts/ig,'').replace(/[\r\n]/g,' ').trim();
const clean=titleRaw.slice(0,76).trim()+' #shorts';
const hashtags=(Array.isArray(o.hashtags)?o.hashtags:[]).map(x=>'#'+String(x).replace(/^#/,'').replace(/[^a-zA-Z0-9_]/g,'')).filter(x=>x.length>1).slice(0,8);
const id='tr-'+Date.now().toString(36)+'-'+String($execution.id||'manual');
return [{json:{lang:'tr',job_id:id,story:{chatTitle:String(o.chatTitle||'Funny Chat').slice(0,28),coverText:String(o.coverText||o.youtubeTitle||'').replace(/#shorts/ig,'').replace(/[\r\n]/g,' ').trim().slice(0,36),dialogue:d},topic:String(o.topic||'').slice(0,120),title:clean,description:String(o.youtubeDescription||'Fictional AI-generated conversation.').slice(0,1000)+'\n\n'+hashtags.join(' ')}}];

const j=$('04 Diyalog ve ses eslemesini dogrula').first().json;
const a=$input.first().json.artifacts||[];
const name='chat-'+j.lang+'-'+j.job_id;
const match=a.find(x=>x.name===name&&!x.expired);
return [{json:{ready:!!match,artifact_id:match?.id||0,job_id:j.job_id}}];

const upload=$input.first().json;const id=upload.id||upload.uploadId;
if(!id)throw new Error('YouTube video ID bulunamadi');
const ctx=$('04 Diyalog ve ses eslemesini dogrula').first().json;
const db=$getWorkflowStaticData('global');
db.usedTopics=Array.isArray(db.usedTopics)?db.usedTopics:[];
db.usedTopics.push(ctx.topic);db.usedTopics=db.usedTopics.slice(-30);
return [{json:{status:'uploaded_private_for_review',youtubeUrl:'https://www.youtube.com/watch?v='+id,language:'tr',title:ctx.title}}];
